window.EQDATA={"gear":{"ATK":{"i":"gear-atk","d":"ATK Set: ATK +15%"},"DEF":{"i":"gear-def","d":"DEF Set: DEF +20%"},"HP":{"i":"gear-hp","d":"HP Set: HP +20%"},"SPD":{"i":"gear-spd","d":"SPD Set: SPD +10%"},"Crit":{"i":"gear-crit","d":"Crit Set: Crit Rate +15%"},"Crit DMG":{"i":"gear-crit-dmg","d":"Crit DMG Set: Crit DMG +20%"},"Hit":{"i":"gear-hit","d":"Hit Set: Effect Hit +20%"},"Tenacity":{"i":"gear-tenacity","d":"Tenacity Set: Tenacity +30%"},"Leech":{"i":"gear-leech","d":"Leech Set: Leech +10%"},"Mastery":{"i":"gear-mastery","d":"Mastery Set: Mastery +20%"},"Healing":{"i":"gear-healing","d":"Healing Set: Healing Effect +20%"},"Resist":{"i":"gear-resist","d":"Resist Set: Effect RES +20%"},"Fearless":{"i":"gear-fearless","d":"Fearless Set: Crit Rate +15%, Leech +10%, Mastery +20%"},"Slay":{"i":"gear-slay","d":"Slay Set: Crit Rate +10%, Crit DMG +15%"},"Wild":{"i":"gear-wild","d":"Wild Set: ATK +8%, Crit Rate +15%"},"Bloodthirsty":{"i":"gear-bloodthirsty","d":"Bloodthirsty Set: ATK +8%, Leech +10%"},"Holy":{"i":"gear-holy","d":"Holy Set: HP +10%, Healing +20%"},"Feather":{"i":"gear-feather","d":"Feather Set: HP +10%, SPD +10%"},"Thorn":{"i":"gear-thorn","d":"Thorn Set: HP +10%, DMG Reflect +20%"},"Tough":{"i":"gear-tough","d":"Tough Set: HP +20%, Tenacity +20%, Effect RES +20%"},"First-aid":{"i":"gear-first-aid","d":"First-aid Set: SPD +10%, Effect Hit +20%, Healing Effect +20%"},"Endurance":{"i":"gear-endurance","d":"Endurance Set: HP +10%, Mastery +20%"},"Guardian":{"i":"gear-guardian","d":"Guardian Set: DEF +15%, Effect RES +20%"},"Hardening":{"i":"gear-hardening","d":"Hardening Set: DEF +15%, Tenacity +30%"},"Accuracy":{"i":"gear-accuracy","d":"Accuracy Set: Mastery +10%, Effect Hit +20%"},"Knight":{"i":"gear-knight","d":"Knight Set: DEF +15%, Crit Rate +15%"},"Penetration":{"i":"gear-penetration","d":"Penetration Set: ATK +8%, Mastery +20%"},"Dexterity":{"i":"gear-dexterity","d":"Dexterity Set: SPD +10%, Effect RES +10%"},"Plunder":{"i":"gear-plunder","d":"Plunder Set: Basic Attack DMG +15%, Leech +8%"},"Absorption":{"i":"gear-absorption","d":"Absorption Set: Skill DMG +15%, Leech +8%"},"Devouring":{"i":"gear-devouring","d":"Devouring Set: Basic Attack DMG +18%, Skill DMG +18%, ATK +10%"},"Fast Killing":{"i":"gear-fast-killing","d":"Fast Killing Set: Crit DMG +25%, Direct DMG +10%, SPD +8%"},"Bone Erosion":{"i":"gear-bone-erosion","d":"Bone Erosion Set: Mastery +25%, DoT DMG +10%, SPD +8%"},"Firm Wind":{"i":"gear-firm-wind","d":"Firm Wind Set: SPD +12%, Tenacity +20%, Mastery RES +20%"},"Swift Blade":{"i":"gear-swift-blade","d":"Swift Blade Set: Direct DMG +15%, Skill DMG +20%, SPD +10%"},"Wind Erosion":{"i":"gear-wind-erosion","d":"Wind Erosion Set: DoT +15%, Skill DMG +20%, SPD +10%"},"Spirit Light":{"i":"gear-spirit-light","d":"Spirit Light Set: Effect Hit +25%, Effect RES +25%, SPD +15%"},"Rapid Rejuvenation":{"i":"gear-rapid-rejuvenation","d":"Rapid Rejuvenation Set: HP +25%, DMG RES +10%, SPD +10%"}},"aura":{"Urgent Treatment":{"i":"aura-urgent-treatment","d":"Healing Effect +9%. This effect is doubled when the target's HP is below 50%.","q":2},"Extreme Evasion":{"i":"aura-extreme-evasion","d":"Reduces the chance of taking a Crit by 13.5%.","q":2},"Pristine Attack":{"i":"aura-pristine-attack","d":"Basic Attacks have 18% more Crit Rate.","q":2},"Range Hit":{"i":"aura-range-hit","d":"Every 1 enemy target increases self Effect Hit, up to 18%.","q":2},"Brutal Recovery":{"i":"aura-brutal-recovery","d":"Restores self HP by 27% of Max HP when inflicting a kill. This effect can only be triggered once each turn.","q":2},"Frenzied Bloodlust":{"i":"aura-frenzied-bloodlust","d":"When landing a Crit, this attack has 24% more Leech.","q":3},"Extra Recovery":{"i":"aura-extra-recovery","d":"Restores self HP by 18% of self Max HP after casting active skills.","q":3},"Victory Rush":{"i":"aura-victory-rush","d":"Increases Direct DMG dealt by 13.5%. This effect additionally increases by 50% for targets under Control status.","q":3},"Mastery Expert":{"i":"aura-mastery-expert","d":"Gains 24% extra Mastery when self HP is above 50%.","q":3},"Campaign Boost":{"i":"aura-campaign-boost","d":"Increases skills' Crit Rate by 16%. This effect is doubled when challenging Campaign stages.","q":3},"Bold Confidence":{"i":"aura-bold-confidence","d":"Crit DMG +24%.\nGains 12% more Crit Rate when self HP is above 90%.","q":4},"Accurate Harvester":{"i":"aura-accurate-harvester","d":"Increase self Turn Meter by 45% when inflicting a kill. This effect can only be triggered once each turn.","q":4},"Hit Master":{"i":"aura-hit-master","d":"Effect Hit +24%.","q":4},"Recovery Horn":{"i":"aura-recovery-horn","d":"Restores all allies' HP by 9% of self Max HP after casting active skills.","q":4},"Deep Targeting":{"i":"aura-deep-targeting","d":"Increases Direct DMG dealt by 18%. Additionally increases DMG dealt by 18% when attacking targets with countered Mark.","q":4},"Fatal Tardiness":{"i":"aura-fatal-tardiness","d":"Gains 27% more Crit Rate when attacking a target under SPD Down status\nand 54% more Crit Rate when attacking a target under Freeze status.","q":4},"Fearless":{"i":"aura-fearless","d":"Reduces Direct DMG taken by 13.5%. Additionally reduces DMG taken by 13.5% when being attacked by targets with countered Mark.","q":4},"Dwarven Blessing":{"i":"aura-dwarven-blessing","d":"Self gains an additional 18% of Max HP, which further increases by 50% in Gate of Nibelungen.","q":4},"Mastery Surge":{"i":"aura-mastery-surge","d":"Mastery +18%.\nGrants Mastery Surge on all allies (excluding self), increasing their Mastery by 18% after casting an active skill. Each target can only have 1 layer of Mastery Surge at any time.","q":4},"Speed Mark":{"i":"aura-speed-mark","d":"SPD +80. This effect is doubled in the Tower of Mark.","q":4},"Shield Smash":{"i":"aura-shield-smash","d":"Piercing Rate +18%.\nGains 36% more ATK when self has a Shield.","q":5},"Bloodthirst":{"i":"aura-bloodthirst","d":"Leech +27%. This effect is doubled when landing a Crit.","q":5},"Boss Slayer":{"i":"aura-boss-slayer","d":"Increases Direct DMG dealt by 32%. This effect additionally increases by 25% when attacking Bosses.","q":5},"Hit Grandmaster":{"i":"aura-hit-grandmaster","d":"HP +27%\nEffect Hit +27%","q":5},"Advanced Hit":{"i":"aura-advanced-hit","d":"ATK +27%\nEffect Hit +27%","q":5},"Survival":{"i":"aura-survival","d":"The lower the HP, the less the DMG taken, up to 40%.","q":5},"Magic Touch":{"i":"aura-magic-touch","d":"Restores self HP by 32% of Max HP after casting the active skill and additionally restores self HP by 8% of Max HP when launching a basic attack.","q":5},"Skill Master":{"i":"aura-skill-master","d":"After self casting active skills, all allies gain DMG Surge, increasing DMG dealt by 27% for 1 turn.","q":5},"Combat Vanguard":{"i":"aura-combat-vanguard","d":"Inflicts Deep DMG on affected targets for 1 turn when dealing Direct DMG, increasing their DMG taken by 36%. Each target can only have 1 layer of Deep DMG at any time.","q":5},"Arena Dominator":{"i":"aura-arena-dominator","d":"SPD +90. This effect is doubled in the Arena.","q":5},"Versatility":{"i":"aura-versatility","d":"Increases skill DMG by 18%. Meanwhile, increases skill DMG Bonus and skill DMG Reduction by 27% in total. (The higher the HP, the higher the skill DMG Bonus; the lower the HP, the higher the Skill DMG RES.)","q":5},"Surging Force":{"i":"aura-surging-force","d":"When a battle starts, Mastery +54%. Increases this bonus to 150% of its original effect for 2 turns when the hero gains [Shield]. The duration will be refreshed when the effect is triggered repeatedly.","q":5},"Heart of Protection":{"i":"aura-heart-of-protection","d":"After casting active skills on an ally as the main target proactively or because of other effects, reduces all allies' Direct DMG and DoT taken by 36% for 2 turns.","q":5},"Bone-gnawing Toxin":{"i":"aura-bone-gnawing-toxin","d":"Increases [Poison] DMG by 60%. For every 1 ally with the [Poison] tag deployed, increases self Skill DMG by 14%, up to 4 layers. Increases DMG Reduction in Arena by 16%.","q":5},"Raging Inferno":{"i":"aura-raging-inferno","d":"Increases [Burn] DMG by 60%. For every 1 ally with the [Burn] tag deployed, increases self Skill DMG by 14%, up to 4 layers. Increases DMG Reduction in Arena by 16%.","q":5},"Heart-piercing":{"i":"aura-heart-piercing","d":"Increases [Internal Injury] DMG by 60%. For every 1 ally with the [Internal Injury] tag deployed, increases self Skill DMG by 14%, up to 4 layers. Increases DMG Reduction in Arena by 16%.","q":5},"Scorching Soul":{"i":"aura-scorching-soul","d":"Increases [HP Burning] DMG by 60%. For every 1 ally with the [HP Burning] tag deployed, increases self Skill DMG by 14%, up to 4 layers. Increases DMG Reduction in Arena by 16%.","q":5},"Unending Bleeding":{"i":"aura-unending-bleeding","d":"Increases [Bleed] DMG by 60%. For every 1 ally with the [Bleed] tag deployed, increases self Skill DMG by 14%, up to 4 layers. Increases DMG Reduction in Arena by 16%.","q":5},"Shattered Cloud":{"i":"aura-shattered-cloud","d":"Increases Piercing by 90%. Increases DMG Reduction in Arena by 16%. Increases Direct DMG dealt by 32%.","q":5}},"echo":{"Burst of Energy":{"i":"echo-burst-of-energy","d":"Increases the owner's Crit DMG by 24%. This effect is reduced by 50% after the end of the first turn of each wave.","q":3},"Weakness Strike":{"i":"echo-weakness-strike","d":"Increases the Direct DMG dealt by the owner to the target with debuffs by 8%. This effect is increased by 50% if the target is under SPD Down status.","q":3},"Fencing Apprentice":{"i":"echo-fencing-apprentice","d":"Reduces the owner's Skill DMG by 20% and increases their Basic Attack DMG by 12%.","q":3},"Skill Master":{"i":"echo-skill-master","d":"Reduces the owner's Basic Attack DMG by 20% and increases their Skill DMG by 12%.","q":3},"Ultimate Defense":{"i":"echo-ultimate-defense","d":"When the owner enters a battle, reduces their ATK by 20% and increases their DEF by 16%.","q":3},"Briar Armor":{"i":"echo-briar-armor","d":"When the owner takes Basic Attack DMG or Skill DMG, they have a 64% chance to inflict a layer of [Bleed] on the attacker for 2 turns. This effect has a CD for 1 turn.","q":3},"Victory Sprint":{"i":"echo-victory-sprint","d":"When the owner acts for 4 turns in total each wave, grants all allies [Strength-gathering Step] until the wave transition. [Strength-gathering Step]: Increases ATK by 8%, up to 1 layer.","q":3},"Divine Barrier":{"i":"echo-divine-barrier","d":"At the beginning of each wave, grants all allies [Unstable Armor]. Removes [Unstable Armor] from all allies when the owner acts for 4 turns in total. [Unstable Armor]: Increases DEF by 16%, up to 1 layer.","q":3},"Breathlessness Waiting":{"i":"echo-breathlessness-waiting","d":"Grants the owner [Quiet Charging] when the owner is under [Stealth] status or is considered as under such status. [Quiet Charging]: Increases the owner's Direct DMG dealt by 18% and DMG Bonus effect on the enemy with countered mark by 9% for 2 turns.","q":4},"Spell-breaking Impact":{"i":"echo-spell-breaking-impact","d":"When the owner casts Active Skills, the main target will be selected until the end of the turn. For every 1 layer of buffs removed or stolen from the selected target, they will gain 1 layer of [Dragonvein Deterrent]: Increases the next stage of Direct DMG taken by the owner by 9%, up to 5 layers.","q":4},"Chivalry":{"i":"echo-chivalry","d":"When the owner casts Active Skills, gains 1 layer of [Gale Combo], each of which increases ATK by 9% for 4 turns, up to 3 layers. Refreshes duration when it is repeatedly gained. Removes all [Gale Combo] from the owner when they are inflicted with buffs or debuffs, and all the effects above cannot be triggered again within 2 turns.","q":4},"Poised Posture":{"i":"echo-poised-posture","d":"If the owner casts Active Skill but fails to deal DMG in their turns, grants them 6 layers of [Self-effecting] at the end of this turn. [Self-effecting]: Removes 2 layers of them when any ally acts and converts all of them to [Sword Out] when the owner acts. [Sword Out]: Until the end of this turn, each layer increases the owners' ATK by 4.5% and additionally increases their Crit DMG by 45% if they have 6 layers of [Sword Out].","q":4},"Unbridled Explosive":{"i":"echo-unbridled-explosive","d":"Each time the owner deals Detonation DMG, grants them 1 layer of [Smoke Diffusion] until the beginning of their next turn. Each layer of [Smoke Diffusion] increases the owner's Crit DMG by 27%, up to 4 layers.","q":4},"Chronic Poison":{"i":"echo-chronic-poison","d":"Increases all allies [Poison] DMG by 13.5% when the owner survives (unstackable with other same effects). Inflicts 1 layer of [Poison] on the owner for 2 turns at the beginning of their turns.","q":4},"Exploding Arrow":{"i":"echo-exploding-arrow","d":"Increases the owner's Crit DMG by 27% when they enter a battle. If their Crit Rate reaches 150% when their turn ends, increases their Crit DMG by 63% instead until the wave transition.","q":4},"Power of Protection":{"i":"echo-power-of-protection","d":"For every 1 ally with [Ally Protection] granted by the owner, grants the owner 1 layer of [Forest Guardian] until the beginning of their next turn. Each layer of [Forest Guardian] increases the owner's Max HP Cap by 4.5% and Healing Effect by 4.5%, up to 4 layers.","q":4},"Battle Specialist":{"i":"echo-battle-specialist","d":"When the owner grants self [Shield] or effects that are considered as [Shield], increases their ATK by 18% and Piercing Rate by 27% for 2 turns.","q":4},"Strike Armor":{"i":"echo-strike-armor","d":"When the owner casts Basic Attack or Skills proactively, increases self DMG Reflect by 1%, up to 30% can be gained this way. Afterward, casts <Powerful Earthquake> for once: All enemies lose HP by 3.6% of the owner's Max HP; for every 1% DMG Reflect owned by the owner, increases enemies' HP Deduction effect by 1.5%, up to 150%.","q":4},"Soul Burning":{"i":"echo-soul-burning","d":"Increases the owner's Mastery by 9% when they enter a battle. If they successfully inflict [HP Burning], the target enters [Fiery Ember]: When inflicted with [Burn], there is a 72% chance to be inflicted with 1 layer of [HP Burning] by the owner for 2 turns. Afterward, removes [Fiery Ember] from the target.","q":4},"Bloody Ice Armor":{"i":"echo-bloody-ice-armor","d":"When the owner enters a battle, increases their DEF by 9% and [Bleed] DMG dealt by 9%. At the beginning of self turn, if self has the highest Max HP or DEF among all allies, increases the boosted effects of self DEF and [Bleed] DMG dealt by 30%. This effect is stackable until the owner's next turn.","q":4},"Ice Cure":{"i":"echo-ice-cure","d":"Restores self HP by 9% of Max HP each time the owner inflicts [Freeze]. If an ally is inflicted with [Freeze] by the owner, restores the ally's HP by 9% of Max HP.","q":4},"Ghost Protection":{"i":"echo-ghost-protection","d":"When the owner enters a battle, increases their Effect RES by 18% of their initial Effect Hit, up to 36%.","q":4},"Silence Domain":{"i":"echo-silence-domain","d":"When the owner inflicts [Silence] or other effects considered as [Silence], absorbs 9% of target's Max HP, up to 27% of self Max HP. Also, at the end of the owner's turn, increases the owner's Turn Meter by 4.5% for every 1 enemy under [Silence] status or considered as under such status.","q":4},"Firepower Attraction":{"i":"echo-firepower-attraction","d":"When the owner is inflicted with [Taunt], restores self HP by 9% of Max HP and gains [Mana Enhancement] for 2 turns. [Mana Enhancement]: Increases self Max HP Cap by 18%.","q":4},"Battle Desire":{"i":"echo-battle-desire","d":"When the owner grants self attribute buffs that can increase ATK, additionally gains [Bright Moonlight]: Increases Direct DMG dealt by 27% for 3 turns. The duration will be refreshed when the effect is triggered repeatedly.","q":4},"Mighty Strength":{"i":"echo-mighty-strength","d":"When the owner reduces the HP of enemies with [Shield], grants self [Fear Devourer]: Increases ATK by 27% for 3 turns.","q":4},"Swift Wit":{"i":"echo-swift-wit","d":"When the owner enters a battle, reduces their Crit Rate by 100% and increases their Crit DMG by 54%.","q":4},"Ocean Legacy":{"i":"echo-ocean-legacy","d":"When the owner enters [Way of Ocean] status, gains [Indomitable Rage]: Increases DEF by 13.5% and Basic Attack DMG by 13.5%. After the owner exits [Way of Ocean] status, [Indomitable Rage] will last for 2 turns.","q":4},"Starlight Afterglow":{"i":"echo-starlight-afterglow","d":"At the beginning of any turn, the owner has a 70% chance to gain 1 layer of [Starlight Power], which increases ATK by 1.8%, up to 10 layers. This chance is not affected by Effect Hit or Effect RES. At the end of the owner's turn, each layer of [Starlight Power] has a 50% chance to be removed automatically. This chance is not affected by Effect Hit or Effect RES. [Starlight Power] can also be removed by others. For every 1 layer of [Starlight Power] removed, restores the owner's HP by 1.8% of self Max HP. [Starlight Power] is regarded as an attribute buff.","q":4},"The Traveler's Diary":{"i":"echo-the-travelers-diary","d":"At the beginning of the owner's turn, grants one of the [Travelogue Pages] randomly to all allies:\n1. Increases all allies' ATK by 9% of the owner's initial ATK.\n2. Increases all allies' Crit DMG by 27%.\n3. Increases all allies' Skill DMG by 9%.\nOnly 1 layer of [Travelogue Page] can be owned at the same time and all allies share the same effect. The effects mentioned above will be removed once the owner dies.","q":4},"Light of Classic":{"i":"echo-light-of-classic","d":"Based on the skills cast by the owner during their turns, increases their ATK until the beginning of their next turn:\n1. Basic Attack: Increases ATK by 9%;\n2. Active Skill: Increases ATK by 27%.","q":4},"Fierce Blow":{"i":"echo-fierce-blow","d":"When the owner inflicts an attribute debuff successfully, they also inflict [Shocking Arrow] on the main target. [Shocking Arrow]: Increases Skill DMG taken by 4.5% for 2 turns. When the owner inflicts [HP Burning] successfully, they also inflict [Soulless Arrow] on the main target. [Soulless Arrow]: Increases [HP Burning] DMG taken by 4.5% for 2 turns. [Shocking Arrow] and [Soulless Arrow] can only be owned by 1 target on each side.","q":4},"Poisonous Miasma":{"i":"echo-poisonous-miasma","d":"When casting active skills, the owner will mark the main target until the end of the turn. For every 1 layer of [Poison] inflicted on the marked target, additionally inflicts 1 layer of [Starlight's Mischief] on them, up to 3 layers, lasting until the owner's next turn or the target gets marked by this effect again. [Starlight's Mischief]: Increases [Poison] DMG taken by 8%.","q":5},"Bloody Fight":{"i":"echo-bloody-fight","d":"When the owner enters a battle, increases their Max HP by 16% and [HP Burning] DMG dealt by 16%. If the owner loses HP because of self skill effect, increases the effects mentioned above by 50% until the end of the owner's turn.","q":5},"Eternal Peace":{"i":"echo-eternal-peace","d":"When the owner enters a battle, increases their Healing Effect by 32%. When the owner loses 12% or more HP each time because of self skill effect, gains [Beacon] for 2 turns if self doesn't have [Beacon]. Otherwise, extends [Beacon]'s duration by 2 turns. [Beacon]: When any ally dies, consumes [Beacon] to restore all remaining allies' HP by 24% of Max HP.","q":5},"Treant's Blessing":{"i":"echo-treants-blessing","d":"When the owner enters a battle, increases their Shield Effect by 32% of their initial Healing Effect, up to 32%. Each time the owner inflicts [Intertwined] or [Heal] or effects considered as [Heal], gains [Vine of Life] for 2 turns. The duration will be refreshed if the effect is triggered repeatedly. [Vine of Life]: Increases Max HP by 16%.","q":5},"Firelord's Support":{"i":"echo-firelords-support","d":"The owner will gain [Holy Flame], which can increase [Burn] DMG dealt by all allies when stacked to a certain number of layer(s):\n1 layer: Increases by 8%;\n2 layers: Increases by 16%;\n3 layers: Increases by 24%.\nAt the beginning of each wave, the owner gains 1 layer of [Holy Flame], which will last until the wave transition; when dealing Detonation DMG, the owner gains 1 layer of [Holy Flame] for 2 turns; when granting allies attribute buffs, the owner gains 1 layer of [Holy Flame] for 4 turns.","q":5},"Blood Craving":{"i":"echo-blood-craving","d":"The owner cannot land a Crit. For every 1 layer of [Bleed] successfully inflicted during the owner's turn, grants self 1 layer of [Blood of Prey] for 2 turns, up to 6 layers. [Blood of Prey]: Increases Mastery by 16%. When [Blood of Prey] is stacked to 6 layers, grants self [Hunting Instinct]: Increases ATK by 24%.","q":5},"Sea God's Protection":{"i":"echo-sea-gods-protection","d":"When the owner enters a battle, increases their Max HP by 320% of their initial DEF. When the owner is under [Way of Ocean] status, increases all allies' (excluding self) Max HP by 96% of the owner's initial DEF. This effect will last for 1 turn if the owner exits [Way of Ocean] and cannot be stacked.","q":5},"Ultimate Relief":{"i":"echo-ultimate-relief","d":"The owner will remove all buffs and debuffs from self before casting active skills. For every 1 effect removed, grants self 1 layer of [Light of Majesty], up to 3 layers until the end of this turn. [Light of Majesty]: Each layer increases Direct DMG and DoT dealt by 24%.","q":5},"Sunbeam Strike":{"i":"echo-sunbeam-strike","d":"For every 1 layer of [HP Burning] successfully inflicted by the owner, deals extra DMG by 1.6% of the target's Max HP, caps at 4.8% of the owner's Max HP. This extra DMG is considered as [HP Burning] DMG.","q":5},"Sincere Cooperation":{"i":"echo-sincere-cooperation","d":"Each time the owner casts an active skill, if an ally takes the next turn, grants them [Arrow of Collaboration] until the end of their turn. Increases ATK of the target with [Arrow of Collaboration] by 2.4% of the owner's initial Max HP. Each target can only have 1 layer of [Arrow of Collaboration]. At the beginning of each turn, if the owner has the highest Max HP among allies, they gain extra 120 SPD until the beginning of their turn. Additionally, the effect of [Arrow of Collaboration] inflicted this turn will be increased by 40%.","q":5},"Impenetrable Defense":{"i":"echo-impenetrable-defense","d":"At the beginning of each wave, grants all allies [Bronze Bell Shield] equal to 8% of the owner's Max HP for 2 turns. [Bronze Bell Shield] can be owned up to 1 layer and cannot be removed. When the owner's Effect RES reaches 250%, increases the Shield value of [Bronze Bell Shield] to 400% of the original. When the owner grants [Stealth] to an ally without [Shield], grants them [Bronze Bell Shield] for 2 turns instead.","q":5},"Persistent Overload":{"i":"echo-persistent-overload","d":"At the beginning of each wave, grants all allies [Recalcitrant Device] for 3 turns, during which the duration will be extended by 1 extra turn if the owner casts active skills. Besides, the owner will gain [Energy Overload] for 1 turn. If the owner's active skills' main target is any ally, the target will gain [Energy Overload] for 1 turn. [Recalcitrant Device]: Increases the Direct DMG and DoT dealt by 8% of the owner's initial Effect RES, up to 16%. [Energy Overload]: Increases Crit DMG dealt by 40%.","q":5},"Bizarre Flame":{"i":"echo-bizarre-flame","d":"When the owner casts active skills, they will randomly get either Raging Flame or Icy Flame (cannot be obtained repeatedly) until the end of the next turn. If the owner has both of them after triggering this effect, extends the duration of them for 1 turn. Increases [Burn] DMG by 24% when having Raging Flame; increases Skill DMG dealt by 24% when having Icy Flame.","q":5},"The Last Stand":{"i":"echo-the-last-stand","d":"When the owner enters a battle, increases their Effect RES by 16%. When the owner inflicts or is inflicted with a debuff, increases their Effect Hit and Effect RES by 32% in total (only debuffs are affected by the bonus). The higher the HP, the higher the Effect Hit; the lower the HP, the higher the Effect RES.","q":5},"Wave Surging":{"i":"echo-wave-surging","d":"At the beginning of each wave, or when triggering counterattacks or pursue-and-attacks, grants self [Wave Treading] for 2 turns. [Wave Treading] reduces the owner's Basic Attack DMG and Skill DMG taken by 24%. If [Wave Treading] granted is because of triggering pursue-and-attacks, increases the owner's Basic Attack DMG and Skill DMG dealt by 32% instead. In the duration of [Wave Treading], there is a 32% chance to block the Control effect taken by the owner, which can only be triggered once each time [Wave Treading] is granted and cannot be stacked. This chance is not affected by Effect Hit or Effect RES.","q":5},"Glory of Guardian":{"i":"echo-glory-of-guardian","d":"When the owner enters a battle, increases Max HP by 24%. Also, if an ally has [Consolidation] or effects considered as [Consolidation] which are granted by the owner, grants [Glory Shield] on them for 3 turns. When the duration of allies' [Glory Shield] ends or when they are granted with [Glory Shield] repeatedly, restores their HP by 10% of the owner's Max HP. This restoration effect can be triggered as well when the ally's HP is lower than 35% or when the owner dies.\n[Glory Shield]: Reduces the chance of getting a Crit by 24%, up to 1 layer.","q":5},"Melodious Piping":{"i":"echo-melodious-piping","d":"When the owner enters a battle, increases their Healing Effect by 24% of their initial Effect Hit, up to 48%. Increases self Max HP by 4% for every 50% Effect Hit owned. The amount below 50% does not provide any Max HP bonus. Also, in the duration of [Heal] owned by allies, increases their Tenacity by 32%, which will last for 1 more turn when they lose [Heal]. Each ally can be affected by 1 [Melodious Piping] only.","q":5},"Remarkable Journey":{"i":"echo-remarkable-journey","d":"When the owner enters a battle, increases Freeze Hit by 24%. When the owner grants [SPD Up] effect, they also grant the target [Surprising Gift] for 2 turns. [Surprising Gift]: Increases Direct DMG and DoT dealt by 18%. If the buff owner is under [SPD Up] status at the beginning of a turn, refreshes the duration of [Surprising Gift].","q":5},"Heartfelt Musicality":{"i":"echo-heartfelt-musicality","d":"Increases the owner's Direct DMG dealt by 24%. While the owner casts active skills targeting a main enemy, the enemy will be inflicted with [Creative Inspiration]. For every 1 stage of Crit DMG dealt by the owner to the target with [Creative Inspiration], the owner gains [Masterpiece] for 2 turns or until the owner inflicts [Creative Inspiration] again. [Masterpiece]: Increases the owner's Skill DMG dealt by 3.2%, up to 12 layers.","q":5},"Nimble Fox":{"i":"echo-nimble-fox","d":"Increases Direct DMG and [Internal Injury] DMG dealt by the owner by 32%. Grants the owner 1 layer of [Sparkly Fox Mark] when they act continuously. [Sparkly Fox Mark]: Increases this effect by 40%, up to 2 layers can be stacked. Will be removed when others act.","q":5},"Indestructible Core":{"i":"echo-indestructible-core","d":"When the owner's Crit DMG is over 150%, 12% of the exceeding part will be converted into extra Max HP, up to 24% extra Max HP can be increased in this way. At the beginning of the owner' turn, if their Crit Rate is not lower than 80%, reduces all allies' DMG taken by 16% for 1 of the owner's turns; this effect cannot be stacked.","q":5},"Marvelous Easter Egg":{"i":"echo-marvelous-easter-egg","d":"When the owner casts an active skill on an ally, grants the ally 1 layer of [Secret of Newborn] (Crit DMG +40%) for 3 turns, up to 3 layers. When the target deals DoT, removes all layers of [Secret of Newborn]. When granting [Secret of Newborn], if the owner's Healing Effect is over 130%, also increases the main target's Turn Meter by 6%.","q":5},"Soul of Sincerity":{"i":"echo-soul-of-sincerity","d":"The owner gains [Wings of Chaos] (Crit DMG +56%) for 1 turn before they pursue and attack. In the duration of [Wings of Chaos], when the owner deals DMG, for every 1 layer of Attribute Debuff owned by the target, increases the owner's Skill DMG dealt by 8%, up to 32%.","q":5},"Omnipotent Control":{"i":"echo-omnipotent-control","d":"For every 1 layer of [Poison] inflicted by the owner on the enemy, deals 50% ATK DoT (random) to self and gains 1 layer of [Venom Mastery] for 2 turns, up to 12 layers can be gained. Each layer of [Venom Mastery] increases [Poison] DMG dealt by 2.7%. When the layers of [Venom Mastery] reach the upper limit, if an enemy takes DMG by triggering [Poison], the enemy will additionally take 96% ATK [Poison] DMG from the owner.","q":5},"Uplifting Drums":{"i":"echo-uplifting-drums","d":"Increases all allies' ATK by 7% when a battle starts.\nIf an ally is inflicted with [Block Removal], the ally will gain 1 layer of [Energizing Notes] at the end of the following 3 turns, up to 1 layer can be gained at the end of each turn. Each layer of [Energizing Notes] increases ATK by 1.4%, up to 40 layers. This effect will not be removed when the owner dies or at the wave transition.\nAdditionally, when an ally is inflicted with [Block Removal] in their first 3 turns each wave, there is a 100% chance to gain 1 extra layer. This chance is not affected by Effect Hit or Effect RES.\nIf the same Echo is equipped by multiple allies at the same time in a battle, only one of them will take effect.","q":5},"Lingering Peril":{"i":"echo-lingering-peril","d":"Increases the owner's Shielded Effect by 35%. When a battle starts, the owner gains 2 layers of [Bloodlust Sword Aura]. Afterward, gains 1 layer of [Bloodlust Sword Aura] after acting for every 2 turns. After the owner casts active skills on enemies when self has any [Shield], consumes 1 layer of [Bloodlust Sword Aura] to pursue and attack the main target with <Bloodlust Sword> once. <Bloodlust Sword>: Deals (20% of the owner's Max HP + 20% of the owner's total Shield value) DMG, caps at 40% of the owner's Max HP. When the owner gains any [Shield] from self or enemies, they can cast <Bloostlust Sword> without having Shield in the next 2 turns; meanwhile, increases <Bloodlust Sword>'s DMG by 100% and the skill has 100% Crit DMG.","q":5},"Soul of Fire":{"i":"echo-soul-of-fire","d":"Increases the owner's Burn DMG dealt by 21%. After the owner launches basic attacks (including pursuit attack and counterattack) during their turns, increases their Basic Attack DMG by 7%, up to 35%, and can only be increased for once each turn. If the owner did not launch any basic attack during their turns, removes all Basic Attack DMG bonus effects gained through the Echo effect.","q":5},"Sleepless Guard":{"i":"echo-sleepless-guard","d":"When the owner enters a battle, increases their Max HP by 18%. When the owner triggers pursue-and-attacks, reduces the target's DMG dealt by 25% for 1 turn, not stackable. If the owner is from The Forgotten, gains 75% Hypnotize, Freeze, and Suffocated RES at the 1st turn of each wave.","q":5},"Mysterious Card":{"i":"echo-mysterious-card","d":"When the owner enters a battle, increases ATK by 18%. If the owner is from Wizard's Eye, they'll gain [Marvelous Card] after increasing self Turn Meter 10 times. After the owner casts an active skill, they will consume [Marvelous Card] to pursue and attack all enemies once, dealing 330% ATK DMG (considered as Skill DMG).","q":5},"Poison of Plant":{"i":"echo-poison-of-plant","d":"Increases the owner's [Poison] DMG dealt by 21%. Each time the ally with [Poison Up] acts for 1 turn, grants the owner 1 layer of [Toxic Mist], additionally increasing the owner's [Poison] DMG dealt\nby 10% of the original, up to 20 layers can be owned. The owner will lose all [Toxic Mist] after dealing Direct DMG.","q":5},"Echoing Melodies":{"i":"echo-echoing-melodies","d":"At the end of the owner's turn, restores 7% of the owner's Max HP for all allies with [Ally Protection]. If the ally who receives the restoration effect has [ATK Up] or [SPD Up], also increases the ally's Skill DMG by 24% of the owner's Healing Effect for 2 turns, up to 36% of Skill DMG can be increased this way for each ally. The same effects cannot be stacked.","q":5},"Pulsating Beat":{"i":"echo-pulsating-beat","d":"For every 1 layer of Attribute debuffs inflicted by the owner, increases the owner's Mastery by 8% for 2 turns, up to 8 times. When the owner pursues and attacks with skills other than basic attacks, additionally increases Skill DMG by 24% and the Mastery bonus effect above to 200% of the original during this pursue-and-attack.","q":5},"Molten Hunt":{"i":"echo-molten-hunt","d":"When the owner gains [Taunt], reduces all allies' DMG taken by 20%, lasting for 1 of the owner's turns. When the owner triggers pursue-and-attack, the Basic Attack DMG dealt by the pursue-and-attack for the even-numbered time is increased by 48%.","q":5},"Wreathing Leaves":{"i":"echo-wreathing-leaves","d":"Increases [Bleed] DMG dealt by the owner by 24%. If the owner is from Foresters, when they launch basic attacks or skills targeting a main enemy proactively, they will additionally cast the skill once:\nDeals 180% ATK [Bleed] DMG to all enemies, with a 100% chance to inflict 1 layer of [Bleed] for 2 turns. The DMG dealt is considered as Skill DMG and can only be triggered once every 2 turns.","q":5},"Whisper of Wind":{"i":"echo-whisper-of-wind","d":"Increases the owner's [Poison] DMG dealt by 32% in others' turns. Each time the owner launches basic attacks in others' turns, the following effects will be triggered:\n1. Restores all allies' HP by 200% of self ATK (not affected by Healing Effect).\n2. Inflicts 1 layer of [Toxic Wind Intrusion] on the target for 3 turns. Each layer increases the target's [Poison DMG] taken by 8%, up to 4 layers can be owned.","q":5},"Sheen of Opulence":{"i":"echo-sheen-of-opulence","d":"Increases the owner's Max HP by 18%. When the turn of the ally with [Ally Protection] granted by the owner begins, increases the owner's Crit DMG by 30% of the ally's Crit DMG (up to 120%) for 2 turns or lasting until the beginning of the next turn of the ally with [Ally Protection] granted by the owner.","q":5},"Promise of Destruction":{"i":"echo-promise-of-destruction","d":"Increases the owner's Leech by 28%. When the owner casts active skills, for every 10% of Leech owned, reduces all enemies' Skill DMG dealt by 5% for 3 turns (up to 35% can be reduced) and increases their Skill DMG taken by 5% for 3 turns (up to 35% can be increased); if the owner is from Sagacity Alliance, this effect can be triggered once at the beginning of each wave, lasting for 1 turn.","q":5},"Dazzling Divine Light":{"i":"echo-dazzling-divine-light","d":"The owner will gain 1 layer of [God's Instruction] (up to 10 layers) each time they cast effects other than basic attacks to pursue and attack.\nWhen the owner casts active skills, [God's Instruction] will be converted into [Generosity] for 2 turns first (up to 5 layers can be converted), each layer of [Generosity] increases Skill DMG dealt by 10.5%.\nIf the owner is from Holy Light Parliament, gains 5 layers of [God's Instruction] at the beginning of each wave and will gain [Immortal] for 1 turn when gaining [Generosity].","q":5},"Immortal Glory":{"i":"echo-immortal-glory","d":"Increases the owner's ATK by 18%. After the owner deducts enemies' Shield value, increases self Piercing Rate and Skill DMG dealt by 24% for 2 turns. If the owner is from Sword Harbor Guards, immune to all control effects before the first turn of each wave ends.","q":5},"Radiant Starlight":{"i":"echo-radiant-starlight","d":"Increases the owner's Shield Effect by 21%. When the turns of the owner or allies with [Ally Protection] begin, their Direct DMG and DoT taken will be reduced by 21%, lasting until their next turn. If the owner has the [HP Burning] tag, there is a 100% fixed chance to cleanse 1 layer of a random debuff from them.","q":5},"Lethal Seduction":{"i":"echo-lethal-seduction","d":"Increases the owner's Skill DMG by 21%. Each time a single enemy is inflicted with 10 layers of [Poison] by the owner, the owner's [Poison] DMG dealt will be increased by 12% for 2 turns, up to 4 layers can be owned.\nIf the owner is from the Doom Legion, after the owner inflicts [Poison] for the first time each wave, grants all allies [Gift of Doom]: Only 1 HP is lost when taking any DMG. Will be removed after taking Basic Attack or Skill DMG 3 time(s). This effect of the same Echo can only be triggered once.","q":5},"Accurate Shooter":{"i":"echo-accurate-shooter","d":"If the owner's initial Crit DMG is over 200%, 18% of the exceed amount will be converted to the owner's Effect Hit, up to 36% can be increased this way. If the owner is from the Nameless Brotherhood, also increases the owner's Basic Attack DMG dealt by 100% of the Effect Hit increased above; besides, when dealing Crit DMG to the Boss or enemies under control effects, this Crit DMG also has 60% Piercing Rate.","q":5},"Lucky Ace":{"i":"echo-lucky-ace","d":"Increases the owner's ATK by 21%. When the owner enters [Resonance Enhancement] status, increases self [Poison] DMG dealt by 21% and all allies' Effect Hit by 18% for 1 of the owner's turns. If the owner is still under [Resonance Enhancement] status at the beginning of their turns, refreshes the duration of effects above.","q":5},"Soul-locking Pursuit":{"i":"echo-soul-locking-pursuit","d":"Increases the owner's DoT dealt by 21%. After the owner casts a skill to pursue and attack, increases the owner's [HP Burning] DMG dealt by 18% (stackable up to 2 times) for 2 turns.","q":5},"Graceful Bloodflame":{"i":"echo-graceful-bloodflame","d":"Increases the owner's Hypnotize Hit by 42%. When the owner gains Resonance Points, if they have no less than 240% Effect Hit and don't have [Power of Bloodflame], grants them [Power of Bloodflame] (increases all allies' Direct DMG and DoT dealt by 28%) for 4 turns; meanwhile, there is a 100% fixed chance to grant all allies 1 layer of [Block Removal] for 2 turns. The same effects cannot be stacked.","q":5},"Wild Hunt of Blood Axe":{"i":"echo-wild-hunt-of-blood-axe","d":"Increases the owner's [Bleed] DMG by 21%. When the owner enters [Resonance Enhancement] status, if self is a Defender and the Healing effect is no lower than 150%, reduces self Skill DMG taken by 40% for 2 turns and other allies can enjoy half of the owner's Skill DMG Reduction effect (unstackable with the same effects). If the owner is under [Resonance Enhancement] status at the beginning of their turns, refreshes the duration of [Protection of Blood Axe] for all allies.","q":5},"Wolf Spirit Chase":{"i":"echo-wolf-spirit-chase","d":"Increases the owner's Direct DMG by 28%. If the owner is from the Dragon Tribe and has the highest DEF among allies, grants all allies [Indomitable II] for 2 turns at the beginning of each wave. Meanwhile, whenever the owner deals [Counterattack] DMG, removes 1 layer of a buff from the target and additionally reduces their Turn Meter by 8%; this effect can be triggered up to 3 time(s) and the count will be reset at the beginning of each enemy's turns.","q":5},"Sugar-coated Bullet":{"i":"echo-sugar-coated-bullet","d":"Increases the owner's Crit DMG by 56%. If the owner is from Holy Light Parliament, when self is under [Resonance Enhancement] status at the beginning of self turn:\n1. Cleanses 3 layer(s) of debuffs from self, prioritizing control effects.\n2. Grants self 1 layer of [Christmas Blessing], increasing ATK and Skill DMG by 13%, up to 5 layers can be stacked.","q":5},"Eternal Holy Light":{"i":"echo-eternal-holy-light","d":"Increases the owner's Max HP by 18%. When the owner grants [Shield] on an ally for the first time, increases self Effect RES by 100% for 2 turns; if the owner is from the Holy Light Parliament, when granting [Shield] on an ally, also grants them [Light of Divinity] (increases Mastery RES and Tenacity by 60%) for 1 turn, up to 2 layers.","q":5},"Light Protection":{"i":"echo-light-protection","d":"Increases the owner's Max HP by 18%. If the owner is from the Sword Harbor Guards, whenever they grant [Shield] on an ally, also grant them [Mighty Light] (increases Skill DMG dealt by 20% of the owner's Shield Effect, up to 120% Shield Effect can be calculated) for 2 turns.","q":5},"Sogdian Whirl":{"i":"echo-sogdian-whirl","d":"When the owner reduces an enemy's Turn Meter or increases an ally's Turn Meter, gains [Graceful Dancing] (increases SPD by 120) until the next turn of self starts, CD: 1 turn. If the owner is from Sunset Sages, when self enters the [Resonance Enhancement] status for the first time each wave, grants [Tenderness] on all allies and inflicts [Intoxicated] on all enemies. [Tenderness]: Blocks the additional Turn Meter Reduction effect received, but Turn Meter starts to be reduced after the blocked reduction effect accumulates to 35%. [Intoxicated]: Blocks the additional Turn Meter Increase effect received, but Turn Meter starts to be increased after the blocked increase effect accumulates to 35%.","q":5},"Arrival of Death":{"i":"echo-arrival-of-death","d":"Each time when the owner starts recording the DMG taken by enemies, grants self [Death Rattle] (increases self Skill DMG by 12%), stackable up to 4 layers and only 1 layer can be stacked during each of self turns. Each time when the owner deals Resonance DMG, grants self [Pale Fire] (increases self Crit DMG by 30%), stackable up to 4 layers and only 1 layer can be stacked during each of self turns.","q":5},"Unrivaled Hunter":{"i":"echo-unrivaled-hunter","d":"Increases the owner's ATK by 18%. If the owner is from the Unruly Outlaws, each time they launch basic attacks, grants self [Shatter] (increases Crit DMG by 60%) for 1 turn; meanwhile, whenever they launch basic attacks 3 times, grants self [Heartseeker] (increases Direct DMG by 48%) for 2 turns.","q":5},"Venom in Velvet":{"i":"echo-venom-in-velvet","d":"When the owner enters a battle, increases Healing Effect by 32%. If the owner is from Unruly Outlaws and is a Supporter:\n1. When granting [HP Up II] to allies each time, additionally increases self Max HP by 25% for 2 turns. The duration will be refreshed if the effect is triggered repeatedly.\n2. When allies launch basic attacks to pursue and attack each time, grants them [Gang's Vigor] (increases Skill DMG by 9%), up to 3 layer(s) can be stacked.","q":5},"Chainsaw Nightmare":{"i":"echo-chainsaw-nightmare","d":"Increases the owner's [Internal Injury] DMG by 21%. After the owner launches basic attacks to pursue and attack or counterattack each time, grants all allies [Bone Crunching]: Increases Basic Attack DMG by 3% for 4 turns, up to 10 layers.","q":5},"Elemental Master":{"i":"echo-elemental-master","d":"Increases the owner's Direct DMG by 28%. If the owner is from Wizard's Eye, before the owner casts skills to pursue and attack:\n1. Increases Piercing by 21% of self Crit DMG for 1 turn, up to 400% Crit DMG can be calculated.\n2. Increases ATK by 10% of self Crit DMG for 1 turn, up to 400% Crit DMG can be calculated.","q":5},"Rushing Tides":{"i":"echo-rushing-tides","d":"After the owner enters a battle, increases Effect Hit by 24%. While the owner is under [Way of Ocean] status:\n1. After an ally deals DoT during their turns, all allies gain 1 layer of [Marine Erosion]: Each layer increases allies' DoT by 3%. Each ally can grant all allies up to 1 layer of [Marine Erosion] every turn, stackable up to 15 layers on each ally. When multiple [Marine Erosion] is obtained, only the strongest one will be owned.\n2. When [Marine Erosion] owned by all survived allies reaches the max limit, the Fatal DMG taken by any ally will consume all [Marine Erosion] owned by allies and the ally will be immune to death this time; meanwhile, restores the ally's HP by 35% of the owner's Max HP. This effect can only be triggered again when [Marine Erosion] owned by all allies reaches the max limit again.","q":5},"Roll of Thunder":{"i":"echo-roll-of-thunder","d":"Increases the owner's Direct DMG by 28%. If the owner is the unit with the highest DEF among all allies, when they grant any ally [Consolidation I], [Consolidation II], [Indomitable I], or [Indomitable II], also inflicts [Thunderous Sound] on all enemies: Reduces DMG dealt by 30% for 1 turn.","q":5},"Sanctuary's Bliss":{"i":"echo-sanctuarys-bliss","d":"Increases the owner's HP by 21%. If the owner is from the Unruly Outlaws and has the highest initial Tenacity among allies, grants all allies [Shadow Barrier]: Reduces Skill DMG taken equal to 35% of the owner's initial Tenacity, up to 42% Skill DMG can be reduced.","q":5},"God of War's Soul":{"i":"echo-god-of-wars-soul","d":"Increases the owner's [Internal Injury] DMG dealt by 28%. After other allies steal attributes from enemies, the owner gains [Fearless Spirit] (increases DMG dealt by 14%) for 2 turns. After stealing attributes from enemies, the owner gains [Divine Justice] (increases Basic Attack DMG dealt by pursue-and-attacks by 42%) for 1 turn.","q":5},"Shadowless Blade":{"i":"echo-shadowless-blade","d":"Increases the owner's Skill DMG by 28%. If the owner is from The Forgotten: 1. For every 10 times [Bleed] DMG is dealt by allies (only 1 time of [Bleed] DMG will be counted during a turn), reduces all of self skills' CD by 1 turn.\n2. For every 10 layers of [Bleed] inflicted by allies, self gains [Frost Blade]: increases [Bleed] DMG by 10.5%, up to 5 layers.","q":5},"Flower Spirit Escort":{"i":"echo-flower-spirit-escort","d":"If the owner is from the Foresters, increases Tenacity and Mastery RES by 80%. At the beginning of each wave and when the owner increases self Turn Meter, the Tenacity and Mastery RES bonus effects mentioned above will be effective on all allies for 2 of the owner's turns; meanwhile, additionally increases the owner's SPD by 165, not stackable and lasting for 2 turns.","q":5},"Chrysanthemum & Sword":{"i":"echo-chrysanthemum-sword","d":"If the owner is from Sword Harbor Guards: 1. Increases self Turn Meter by 10% each time they are immune to control effects, up to 3 times can be triggered before the next turn of self starts.\n 2. After casting skills proactively each time, gains 1 layer of [Bushido] (increasing Skill DMG by 12%, up to 6 layers).","q":5},"Seaside Vacation":{"i":"echo-seaside-vacation","d":"Increases the owner's Crit DMG by 60%. If the owner is from Nameless Brotherhood,\n1. When the owner casts active skills to pursue and attack or counterattack, gains [Wave Current]: increases Skill DMG by 35%.\n2. When the owner deals [Internal Injury] DMG, gains [Flowing Waves]: increases Direct DMG by 35% for 1 turn, not stackable and can only be triggered once in anyone's turn.","q":5},"Angel of Death":{"i":"echo-angel-of-death","d":"Increases the owner's ATK by 28%. If the owner is from Doom Legion,\n1. When the owner lands a Crit under [Stealth] status, increases Piercing rate by 100%.\n2. Each time after the owner launches a basic attack, increases self Basic Attack DMG by 28%, up to 2 layers and will be removed when anyone's turn ends.","q":5},"Electric Spark":{"i":"echo-electric-spark","d":"Reduces the owner's DMG taken by 40%. If the owner is from Wizard's Eye, when reducing enemies' Turn Meters by casting active skills, grants all allies [Battery Charging] (increases DMG dealt by 30%) for 2 turns, not stackable.","q":5},"Inferno Shadow":{"i":"echo-inferno-shadow","d":"Increases the owner's ATK by 21%.\nIf the owner is from Unruly Outlaws, they gain 1 layer of [Flame] after casting active skills to pursue and attack each time. [Flame]: increases self [Burn] DMG by 21% for 2 turns, up to 3 layers.","q":5},"Unleash the Wildness":{"i":"echo-unleash-the-wildness","d":"Increases the owner's [HP Burning] DMG dealt by 21%.\nIf the owner is from Dragon Tribe, each time they grant [HP Burning UP II] to an ally:\n1. If the ally's initial HP is lower than the owner's, grants the ally [Peerless Youth]: reduces Skill DMG taken by 30% for 2 turns.\n2. If the ally's initial HP is not lower than the owner's, grants the ally [Brute Force]: increases Skill DMG dealt by 30% for 2 turns.\nThe owner will gain [Peerless Youth] and [Brute Force] equal to 60% of the above value for 2 turns.\n[Peerless Youth] and [Brute Force] are not stackable.","q":5},"Devil's Shadow":{"i":"echo-devils-shadow","d":"Increases the owner's DoT dealt by 21%.\nIf the owner is from the Doom Legion, when they grant [Poison Up II] to allies, they gain [Devil's Horns]: Increases Skill DMG by 48% for 3 turns.","q":5},"Chill of Winter":{"i":"echo-chill-of-winter","d":"Increases the owner's Crit DMG by 60%.\nIf the owner is from The Forgotten, when they steal attributes from any enemy:\n1. If the owner has the highest initial HP among all allies, grants all allies [Wall of Wind]: reduces Skill DMG taken equal to 60% of the owner's initial Skill DMG for 2 turns.\n2. They gain [Mild Winter]: increases Max HP by 12%, up to 20 layers. This effect can only be triggered once in any turn.","q":5},"Divine Glow":{"i":"echo-divine-glow","d":"Increases the owner's ATK by 21%.\nIf the owner is from Holy Light Parliament:\n1. When the owner steals attributes from enemies, the owner gains [Golden Light]: increases DoT dealt by self by 30% for 4 turns.\n2. When the owner grants [ATK Up II] to allies, the owner gains [Heaven's Blessing]: increases Skill DMG dealt by self by 30% for 4 turns.","q":5},"Moonlight Protection":{"i":"echo-moonlight-protection","d":"Increases the owner's HP by 21%. If the owner is from the Foresters, when granting [Stealth] to an ally:\n1. The owner additionally gains 120 SPD.\n2. Increases all allies' Skill DMG by 20% of the owner's initial Healing Effect for 2 turns, caps at 120% Healing Effect. The Echo effect cannot be stacked.","q":5},"King of Tundra":{"i":"echo-king-of-tundra","d":"If the owner is from The Forgotten:\n1. When the owner grants an ally [Snow Wall], also increases all allies' Max HP by 30% of the owner's initial HP for 3 turns.\n2. When the owner grants an ally [Mastery Up II], also grants all allies [Savage Roar]: increases DMG dealt by 30% for 3 turns.","q":5},"Azure Ocean Spirit":{"i":"echo-azure-ocean-spirit","d":"Increases the owner's Max HP by 21%.\nIf the owner is from Hidden Wave, when they grant [Mastery Up II] to allies, grants [Overlapping Waves] to 2 allies with the highest initial ATK. [Overlapping Waves]: Increases Skill DMG by 60% of the Echo owner's initial Healing Effect for 4 turns, up to 100% Healing Effect can be calculated.","q":5},"Death Knight":{"i":"echo-death-knight","d":"Increases the owner's Burn DMG by 28%.\nIf the owner is from Eternal Sect, when the owner deals Detonation DMG to enemies:\n1. Gains [Soulbind]: increases self Skill DMG by 42% for 2 turns.\n2. Gains [Sprint]: increases self SPD by 2%, up to 10 layers. This effect can only be triggered once during a turn.","q":5},"King of Medicine":{"i":"echo-king-of-medicine","d":"If the owner is from Sagacity Alliance: \n1. When granting [ATK Up II] to allies, also grants all allies [Strength Potion]: increases DMG by 16% for 2 turns.\n2. When granting [Internal Injury Up II] to allies, also grants all allies [Heartening Potion]: increases Skill DMG by 16% for 2 turns.","q":5},"Valor of Sword Harbor":{"i":"echo-valor-of-sword-harbor","d":"Increases the owner's Mastery by 36%.\nIf the owner is from Sword Harbor Guards: \n1. When granting [Mastery Up II] to allies, gains [Superior Firepower] (increases DMG dealt by self by 48%) for 2 turns.\n2. When granting [Speed Up II] to allies, also grants all allies [Astute Deployment] (increases all allies' Skill DMG dealt by 24%) for 2 turns.\n[Superior Firepower] and [Astute Deployment] end in advance when the owner grants allies any [Shield].","q":5},"Magic Boxer":{"i":"echo-magic-boxer","d":"If the owner is from the Wizard's Eye, the owner grants all allies [Overpower] when they grant any [Shield] or [SPD Up II] to allies. [Overpower]: Increases Skill DMG by 30% of the owner's initial Healing Effect, lasting for 3 turns, up to 130% Healing Effect can be calculated.","q":5},"Magic Present":{"i":"echo-magic-present","d":"Increases the owner's DMG dealt by 21%.\nIf the owner is from Wizard's Eye, each of the following effects can be triggered once in any turn:\n1. After the owner deals Direct DMG once, gains [Wish] (increases self Mastery by 120%), lasting for 1 turn.\n2. After the owner deals [Detonation] DMG once, gains [Grand Gift] (increases self Skill DMG by 2.5%), up to 20 layers.","q":5},"Great Guardian":{"i":"echo-great-guardian","d":"Increases the owner's HP by 21%.\nIf the owner is from Sword Harbor Guards: \n1. When an ally pursues and attacks, increases their DMG dealt by 16% in the duration.\n2. After allies pursue and attack 4 times in any turn, grants all allies [Prestige] (increases Skill DMG by 16%) for 2 turns.","q":5},"Kalpa Flame":{"i":"echo-kalpa-flame","d":"Increases the owner's [Poison] DMG by 21%.\nIf the owner is from Sagacity Alliance: \n1. At the beginning of any turn, for every 1 ally with the [Counterattack] tag deployed, the owner gains [Prime] (increases Skill DMG by 8%), lasting until anyone's next turn starts.\n2. When the owner grants [Counterattack] to any ally, the owner gains [Ire] (increases ATK by 2%), up to 20 layers. This effect can be triggered once in any turn.","q":5},"Lord of Demon Realm":{"i":"echo-lord-of-demon-realm","d":"Increases the owner's [Bleed] DMG by 21%.\nIf the owner is from Eternal Sect: \n 1. Grants all allies [ATK Up II] for 2 turns at the beginning of the owner's waves.\n2. The owner gains [Demonic Empowerment] (increases Basic Attack DMG by 28%) after each stage of DMG hits enemies successfully, up to 2 layers, and this effect will be removed when any unit's turn ends.","q":5},"Nether King":{"i":"echo-nether-king","d":"Increases the owner's Shield Effect by 35%.\nIf the owner is from Eternal Sect: \n1. When the owner grants [Burn Up II] to allies, gains [Nether King's Aftermath] (increases Skill DMG by 42%) for 2 turns.\n2. Grants [Soul Surge] to the 2 allies with the highest initial ATK. [Soul Surge]: Increases Skill DMG by 60% of the Echo owner's initial Shield Effect, up to 100% Shield Effect can be calculated.","q":5},"Divine Martial Sovereign":{"i":"echo-divine-martial-sovereign","d":"Increases the owner's [Loong's Wrath] DMG dealt by 21%.\nIf the owner is from Sword Harbor Guards: \nWhen the owner inflicts [Loong's Wrath] on enemies:\n1. Gains [Divine Might] (increases Skill DMG by 42%) for 2 turns.\n2. Detonates all [HP Burning] and [Loong's Wrath] owned by targets and increases the duration of [HP Burning] and [Loong's Wrath] by 6 turn(s).","q":5},"Mech Berserker":{"i":"echo-mech-berserker","d":"Increases the owner's Direct DMG by 35%.\nIf the owner is from Nameless Brotherhood:\n1. When the owner inflicts [Severe Wound] on an enemy, gains [Flash] (increases Skill DMG by 42%) for 2 turns.\n2. When the owner deals DMG, inflicts 1 layer of [Corrosion] on the target for 2 turns. [Corrosion]: Increases Direct DMG taken by 5%, cannot be removed, up to 6 layers.","q":5},"Loong Sovereign":{"i":"echo-loong-sovereign","d":"Increases the owner's Shield Effect by 36%.\nIf the owner is from Sagacity Alliance: \n1. When the owner enters a battle, for every 1 ally with the [Internal Injury] tag deployed, the owner gains 1 layer of [Leaping Loong] (each layer increases Skill DMG by 8%).\n2. When the owner grants any ally a [Shield], also grants them 1 layer of [ATK Up II] for 1 turn.","q":5},"Thrust of the Fallen God":{"i":"echo-thrust-of-the-fallen-god","d":"Increases the owner's [Bleed] DMG by 21%.\nIf the owner is from Nameless Brotherhood:\n1. Each time the owner deals Basic Attack DMG or Skill DMG, gains [Crimson Haze] (increases [Bleed] DMG by 12%), up to 5 layers.\n2. When [Crimson Haze] reaches its max layers, increases Mastery by 50%.","q":5},"Torrid Spring":{"i":"echo-torrid-spring","d":"Increases the owner's Healing Effect by 21%.\nIf the owner is from Foresters:\n1. For each ally with the [HP Burning], [HP Deduction], or [Burn] tag deployed, grants [Spirit Bloom] to all allies. [Spirit Bloom]: Increases DoT dealt by 12%.\n2. Each time an ally (excluding the owner) deals [Burn] or [HP Burning] DMG, additionally deals [Burn] DMG equal to 5% of the target's Max HP (caps at 10% of Brigid's Max HP); this cap is increased to 1000% of Brigid's Max HP against Boss targets.","q":5},"Moongazing Phantom":{"i":"echo-moongazing-phantom","d":"Increases the owner's [Poison] DMG dealt by 21%.\nIf the owner is from Sword Harbor Guards:\n1. When dealing [Poison] DMG, increases the target's DoT taken by 30%, up to 5 layers, lasting for 2 turns.\n2. When dealing [Poison] DMG to a Boss, increases the target's [Poison] DMG taken by 30% and reduces Mastery RES by 30%, up to 5 layers, lasting for 2 turns. Meanwhile, additionally increases the owner's [Poison] DMG dealt by 100% and Mastery by 100%.\n3. When 5 allies with the [Poison] or [Attribute Steal] tag are deployed, grants all allies [Koka Sorcery]: increases DoT dealt by 30% and reduces Basic Attack DMG and Skill DMG taken by 30%.","q":5},"Golden Sand Reverie":{"i":"echo-golden-sand-reverie","d":"Increases the owner's Skill DMG by 21%.\nIf the owner is from Sunset Sages:\n1. Can trigger up to 4 times per battle: if an enemy does not proactively cast a skill during their turn, grants 1 layer of [Mirage Sandguard] to all allies (reduces DMG taken to 1 and removes 1 layer after taking Basic Attack DMG or Skill DMG).\n2. When the owner deals [Poison] DMG outside of their own turn, increases their [Poison] DMG dealt by 2%, up to 25 layers.","q":5},"Crown of the Deep":{"i":"echo-crown-of-the-deep","d":"Amphitrite’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Azure Demon Mask":{"i":"echo-azure-demon-mask","d":"Genjiro’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Soul Dominance":{"i":"echo-soul-dominance","d":"Hades’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Netherworld Ghost Pact":{"i":"echo-netherworld-ghost-pact","d":"Izanami’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Verdant Crown":{"i":"echo-verdant-crown","d":"Olenna’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Shadow Chaser":{"i":"echo-shadow-chaser","d":"Skadi’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Illusory Oiran":{"i":"echo-illusory-oiran","d":"Suzuran’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Sand Mirage":{"i":"echo-sand-mirage","d":"Taz’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Primal Spitfire":{"i":"echo-primal-spitfire","d":"Ulrik’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Demonhunter Wolf":{"i":"echo-demonhunter-wolf","d":"White’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1},"Twilight Wanderer":{"i":"echo-twilight-wanderer","d":"Boone’s signature Echo. Full effect text isn’t in the game files yet.","q":5,"nd":1}}};
